// HSK 3.0 curriculum (Giáo trình) screen #screenCurriculum: level picker, lesson list
// and lesson pages (vocabulary, grammar, dialogue, practice quiz) built from
// database/curriculum/hsk30/*.json (generated by tools/build_curriculum.py).
// Each lesson also registers a flashcard deck in LEVELS so its words reuse the
// existing flashcard + spaced repetition pipeline.
import { render } from 'preact';
import { CURRICULUM_LESSONS } from './curriculumIndex';
import {
  AudioIcon,
  CheckIcon,
  ArrowRightIcon,
  ChevronLeftIcon,
  RotateIcon,
} from './Icons.jsx';

/* global LEVELS, selectLevel, speakText, speakSequence, readSavedLevelProgress, SpaRouter, primaryTab, APP_VERSION */

const DATA_ROOT = 'database/curriculum/hsk30/';
const STORE_KEY = 'hsk_curriculum_v1';
const PASS_RATIO = 0.8;
const QUIZ_SIZE = 10;
const LISTENING_QUIZ_LIMIT = 3;
const GRAMMAR_QUIZ_LIMIT = 4;
const OPTION_DISTRACTORS = 3;
const MIN_GRAMMAR_DISTRACTORS = 2;
const SECTIONS = [
  ['vocab', 'Từ mới'],
  ['dialogue', 'Bài đọc'],
  ['grammar', 'Ngữ pháp'],
  ['practice', 'Luyện tập'],
];
const LESSON_NUMERALS = ['', '一', '二', '三', '四', '五', '六', '七', '八', '九', '十'];

let screenEl = null;
let indexData = null;
let indexPromise = null;
const levelCache = {};
const deckCache = {};
let ui = { level: null, lessonKey: null, quiz: null, hidePinyin: false, showAllWords: false, showGuide: false, error: null };

function versionSuffix() {
  try { return typeof APP_VERSION !== 'undefined' ? '?v=' + APP_VERSION : ''; } catch (e) { return ''; }
}

function readStore() {
  try {
    const raw = JSON.parse(localStorage.getItem(STORE_KEY) || '{}');
    return { lessons: raw.lessons || {}, level: raw.level || null, last: raw.last || null };
  } catch (e) {
    return { lessons: {}, level: null, last: null };
  }
}

function writeStore(patch) {
  const next = { ...readStore(), ...patch };
  try { localStorage.setItem(STORE_KEY, JSON.stringify(next)); } catch (e) {}
  return next;
}

function recordQuizResult(key, score, total) {
  const store = readStore();
  const prev = store.lessons[key] || {};
  const pct = total ? Math.round((score / total) * 100) : 0;
  const lessons = {
    ...store.lessons,
    [key]: { best: Math.max(prev.best || 0, pct), done: Boolean(prev.done) || pct >= PASS_RATIO * 100, at: Date.now() },
  };
  writeStore({ lessons });
}

export function lessonNumeral(n) {
  if (n <= 10) return LESSON_NUMERALS[n];
  const tens = Math.floor(n / 10);
  const ones = n % 10;
  return (tens > 1 ? LESSON_NUMERALS[tens] : '') + '十' + (ones ? LESSON_NUMERALS[ones] : '');
}

function knownCount(key) {
  if (typeof readSavedLevelProgress !== 'function') return 0;
  try {
    return Object.values(readSavedLevelProgress(key) || {}).filter((s) => s === 'known').length;
  } catch (e) {
    return 0;
  }
}

async function fetchJson(url) {
  const res = await fetch(url + versionSuffix());
  if (!res.ok) throw new Error('fetch failed: ' + url);
  return res.json();
}

function loadIndex() {
  if (indexData) return Promise.resolve(indexData);
  if (!indexPromise) {
    indexPromise = fetchJson(DATA_ROOT + 'index.json').then((data) => {
      indexData = data;
      return data;
    }).finally(() => { indexPromise = null; });
  }
  return indexPromise;
}

function loadLevel(levelId) {
  if (levelCache[levelId]) return Promise.resolve(levelCache[levelId]);
  return fetchJson(DATA_ROOT + 'level' + levelId + '.json').then((data) => {
    levelCache[levelId] = data;
    return data;
  });
}

function loadDeck(key) {
  if (deckCache[key]) return Promise.resolve(deckCache[key]);
  return fetchJson(DATA_ROOT + 'decks/' + key + '.json').then((data) => {
    deckCache[key] = data;
    return data;
  });
}

function levelIdOfLesson(key) {
  const m = /^cur30_(\d+)_\d+$/.exec(key || '');
  return m ? m[1] : null;
}

function shuffle(list) {
  const arr = list.slice();
  for (let i = arr.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function pickDistractors(pool, correct, count) {
  const seen = new Set([correct]);
  const out = [];
  for (const item of shuffle(pool)) {
    if (!item || seen.has(item)) continue;
    seen.add(item);
    out.push(item);
    if (out.length >= count) break;
  }
  return out;
}

export function buildQuiz(lesson, levelData) {
  const questions = [];
  const words = (lesson.words || []).filter((w) => w.hanzi && w.meaning);
  const meanings = words.map((w) => w.meaning);
  const hanzis = words.map((w) => w.hanzi);

  const listeningQs = [];
  const dialogueLines = (lesson.dialogue || []).filter((l) => l.zh && l.vi);
  const dialogueViPool = [];
  (levelData.lessons || []).forEach((l) => {
    (l.dialogue || []).forEach((line) => { if (line.vi) dialogueViPool.push(line.vi); });
  });
  shuffle(dialogueLines).slice(0, LISTENING_QUIZ_LIMIT - 1).forEach((line) => {
    const distractors = pickDistractors(dialogueViPool, line.vi, OPTION_DISTRACTORS);
    if (distractors.length < MIN_GRAMMAR_DISTRACTORS) return;
    listeningQs.push({
      kind: 'Nghe câu và chọn nghĩa',
      prompt: '',
      promptIsZh: false,
      audioText: line.zh,
      options: shuffle([line.vi, ...distractors]),
      answer: line.vi,
      optionsZh: false,
      explain: `${line.zh} · ${line.py} — ${line.vi}`,
    });
  });
  shuffle(words).slice(0, LISTENING_QUIZ_LIMIT - listeningQs.length).forEach((w) => {
    const distractors = pickDistractors(hanzis, w.hanzi, OPTION_DISTRACTORS);
    if (distractors.length < MIN_GRAMMAR_DISTRACTORS) return;
    listeningQs.push({
      kind: 'Nghe từ và chọn chữ Hán',
      prompt: '',
      promptIsZh: false,
      audioText: w.hanzi,
      options: shuffle([w.hanzi, ...distractors]),
      answer: w.hanzi,
      optionsZh: true,
      explain: `${w.hanzi} · ${w.pinyin} — ${w.meaning}`,
    });
  });

  const keyPool = [];
  (levelData.lessons || []).forEach((l) => (l.grammar || []).forEach((g) => { if (g.key) keyPool.push(g.key); }));
  const grammarQs = [];
  (lesson.grammar || []).forEach((g) => {
    (g.examples || []).forEach((ex) => {
      if (!g.key || ex.zh.indexOf(g.key) < 0) return;
      const distractors = pickDistractors(
        keyPool.filter((k) => ex.zh.indexOf(k) < 0 || k === g.key),
        g.key,
        OPTION_DISTRACTORS,
      );
      if (distractors.length < MIN_GRAMMAR_DISTRACTORS) return;
      grammarQs.push({
        kind: 'Điền vào chỗ trống',
        prompt: ex.zh.replace(g.key, ' ＿＿ '),
        promptIsZh: true,
        sub: ex.vi,
        options: shuffle([g.key, ...distractors]),
        answer: g.key,
        optionsZh: true,
        explain: `${g.title}: ${g.formula}`,
      });
    });
  });

  const pickedListening = shuffle(listeningQs).slice(0, LISTENING_QUIZ_LIMIT);
  const pickedGrammar = shuffle(grammarQs).slice(0, GRAMMAR_QUIZ_LIMIT);
  const vocabTarget = Math.min(words.length, QUIZ_SIZE - pickedListening.length - pickedGrammar.length);
  shuffle(words).slice(0, vocabTarget).forEach((w, i) => {
    if (i % 2 === 0) {
      const opts = shuffle([w.meaning, ...pickDistractors(meanings, w.meaning, OPTION_DISTRACTORS)]);
      questions.push({ kind: 'Chọn nghĩa đúng', prompt: w.hanzi, promptIsZh: true, options: opts, answer: w.meaning, optionsZh: false, explain: `${w.hanzi} · ${w.pinyin} — ${w.meaning}` });
    } else {
      const opts = shuffle([w.hanzi, ...pickDistractors(hanzis, w.hanzi, OPTION_DISTRACTORS)]);
      questions.push({ kind: 'Chọn từ đúng nghĩa', prompt: w.meaning, promptIsZh: false, options: opts, answer: w.hanzi, optionsZh: true, explain: `${w.hanzi} · ${w.pinyin} — ${w.meaning}` });
    }
  });
  questions.push(...pickedListening, ...pickedGrammar);
  return { questions: shuffle(questions), index: 0, picked: null, score: 0, finished: false };
}

function rerender() {
  if (screenEl) render(<CurriculumScreen />, screenEl);
}

function setUi(patch) {
  ui = { ...ui, ...patch };
  rerender();
}

function pushRoute(lessonKey) {
  if (typeof SpaRouter === 'undefined') return;
  if (SpaRouter.isNavigatingFromPopstate && SpaRouter.isNavigatingFromPopstate()) return;
  SpaRouter.pushView(lessonKey ? { view: 'tab', tab: 'curriculum', lesson: lessonKey } : { view: 'tab', tab: 'curriculum' });
}

function selectCurriculumLevel(levelId) {
  writeStore({ level: levelId });
  setUi({ level: levelId, lessonKey: null, quiz: null, showAllWords: false });
  loadLevel(levelId).then(rerender).catch(() => setUi({ error: 'Không tải được dữ liệu giáo trình.' }));
}

export async function openLesson(key, push = true) {
  const levelId = levelIdOfLesson(key);
  if (!levelId) return;
  writeStore({ level: levelId, last: key });
  ui = { ...ui, level: levelId, lessonKey: key, quiz: null, showAllWords: false, error: null };
  rerender();
  if (push) pushRoute(key);
  try {
    await Promise.all([loadIndex(), loadLevel(levelId)]);
  } catch (e) {
    setUi({ error: 'Không tải được dữ liệu giáo trình.' });
    return;
  }
  rerender();
  window.scrollTo({ top: 0, behavior: 'instant' });
}

function backToLessons() {
  setUi({ lessonKey: null, quiz: null });
  pushRoute(null);
  window.scrollTo({ top: 0, behavior: 'instant' });
}

function startLessonFlashcards(key) {
  if (typeof selectLevel === 'function') selectLevel(key);
  else if (window.selectLevel) window.selectLevel(key);
}

function speak(text, event) {
  const button = event && event.currentTarget;
  if (typeof speakText === 'function') speakText(text, button);
  else if (window.speakText) window.speakText(text, button);
}

function speakAll(texts, event) {
  const button = event && event.currentTarget;
  if (typeof speakSequence === 'function') speakSequence(texts, button);
  else if (window.speakSequence) window.speakSequence(texts, button);
}

function scrollToSection(id) {
  const el = document.getElementById('curSection-' + id);
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function isDone(store, key) {
  return Boolean(store.lessons[key] && store.lessons[key].done);
}

function LevelPicker({ levels, active, store }) {
  return (
    <div class="cur-levels" role="tablist" aria-label="Chọn cấp độ giáo trình">
      {levels.map((lv) => {
        const done = lv.lessons.filter((l) => isDone(store, l.key)).length;
        const complete = lv.lessons.length > 0 && done === lv.lessons.length;
        const meta = complete ? 'Đã hoàn thành' : done ? `${done}/${lv.lessons.length} bài` : `${lv.lessons.length} bài · ${lv.words} từ`;
        return (
          <button
            type="button"
            role="tab"
            aria-selected={String(lv.level === active)}
            class={'cur-level-chip' + (lv.level === active ? ' active' : '') + (complete ? ' is-complete' : '')}
            onClick={() => selectCurriculumLevel(lv.level)}
          >
            <span class="cur-level-name">
              {lv.name}
              {complete && <span class="cur-level-check" aria-label="Đã hoàn thành"><CheckIcon size={12} /></span>}
            </span>
            <span class="cur-level-meta">{meta}</span>
          </button>
        );
      })}
    </div>
  );
}

function LevelProgressBar({
  levelName,
  pct,
  doneLessons,
  totalLessons,
  knownWords,
  totalWords,
  grammarDone,
  grammarTotal,
  currentLesson,
  featureState,
  onStartLesson,
}) {
  const ctaLabel = featureState === 'complete'
    ? 'Ôn lại bài'
    : featureState === 'continue'
      ? `Học tiếp · Bài ${currentLesson ? currentLesson.n : ''}`
      : `Bắt đầu · Bài ${currentLesson ? currentLesson.n : ''}`;
  return (
    <section class="cur-progress-bar" aria-label={`Tiến độ ${levelName}`}>
      <div class="cur-pb-info">
        <div class="cur-pb-top">
          <span class="cur-pb-title">{`Tiến độ ${levelName}`}</span>
          <span class="cur-pb-pct">{`${pct}%`}</span>
        </div>
        <div
          class="cur-progress"
          role="progressbar"
          aria-valuemin="0"
          aria-valuemax="100"
          aria-valuenow={pct}
          aria-label={`Tiến độ ${levelName}`}
        >
          <div class="cur-progress-fill" style={`width:${pct}%`}></div>
        </div>
        <div class="cur-pb-stats">
          <span><strong>{doneLessons}</strong>{`/${totalLessons} bài`}</span>
          <span class="cur-pb-dot" aria-hidden="true">·</span>
          <span><strong>{knownWords}</strong>{`/${totalWords} từ đã nhớ`}</span>
          <span class="cur-pb-dot" aria-hidden="true">·</span>
          <span><strong>{grammarDone}</strong>{`/${grammarTotal} ngữ pháp`}</span>
        </div>
      </div>
      {currentLesson && (
        <button
          type="button"
          class="ds-btn ds-btn--primary cur-pb-cta"
          onClick={() => onStartLesson(currentLesson.key)}
        >
          {ctaLabel}
          <ArrowRightIcon size={16} />
        </button>
      )}
    </section>
  );
}

function OverviewView({ index, levelId }) {
  const store = readStore();
  const level = index.levels.find((l) => l.level === levelId) || index.levels[0];
  const details = {};
  ((levelCache[level.level] && levelCache[level.level].lessons) || []).forEach((l) => { details[l.key] = l; });
  const doneCount = level.lessons.filter((l) => isDone(store, l.key)).length;
  const knownWords = level.lessons.reduce((sum, l) => sum + knownCount(l.key), 0);
  const grammarDone = level.lessons.reduce((sum, l) => sum + (isDone(store, l.key) ? l.grammar : 0), 0);
  const grammarInLessons = level.lessons.reduce((sum, l) => sum + l.grammar, 0);
  const lastKey = store.last && level.lessons.some((l) => l.key === store.last) ? store.last : null;
  const nextLesson = level.lessons.find((l) => !isDone(store, l.key)) || level.lessons[level.lessons.length - 1];
  const current = lastKey && !isDone(store, lastKey) ? level.lessons.find((l) => l.key === lastKey) : nextLesson;
  const pct = level.lessons.length ? Math.round((doneCount / level.lessons.length) * 100) : 0;
  const levelComplete = level.lessons.length > 0 && doneCount === level.lessons.length;
  const featureState = levelComplete ? 'complete' : (doneCount || (current && store.lessons[current.key])) ? 'continue' : 'start';
  return (
    <div class="cur-wrap">
      <header class="cur-hero-compact">
        <div class="cur-eyebrow">Lộ trình HSK 3.0 · 9 cấp (11.000 từ)</div>
        <h2 class="cur-title" tabindex="-1">Giáo trình HSK 3.0</h2>
      </header>

      <LevelPicker levels={index.levels} active={level.level} store={store} />

      <LevelProgressBar
        levelName={level.name}
        pct={pct}
        doneLessons={doneCount}
        totalLessons={level.lessons.length}
        knownWords={knownWords}
        totalWords={level.words}
        grammarDone={grammarDone}
        grammarTotal={grammarInLessons}
        currentLesson={current}
        featureState={featureState}
        onStartLesson={openLesson}
      />

      <div class="cur-main">
        <div class="cur-list-head">
          <div class="cur-list-title-wrap">
            <h3 class="cur-h2">{`${level.name} · ${level.lessons.length} bài`}</h3>
            <button
              type="button"
              class="cur-guide-toggle"
              aria-expanded={String(ui.showGuide)}
              aria-controls="curLessonGuide"
              onClick={() => setUi({ showGuide: !ui.showGuide })}
              title="Cấu trúc mỗi bài học"
            >
              ?
            </button>
          </div>
          <span class="cur-list-meta">{`${level.words} từ · ${grammarInLessons} điểm ngữ pháp trọng tâm`}</span>
        </div>

        {ui.showGuide && (
          <div id="curLessonGuide" class="cur-guide-box">
            <strong>Mỗi bài gồm 4 phần:</strong>
            <span>1. Từ mới (flashcard SRS) · 2. Bài đọc (hội thoại theo ngữ cảnh) · 3. Ngữ pháp (công thức &amp; ví dụ) · 4. Luyện tập (đạt ≥ 80% để hoàn thành).</span>
          </div>
        )}

        <ol class="cur-lesson-list">
          {level.lessons.map((l) => {
            const rec = store.lessons[l.key];
            const state = rec && rec.done ? 'done' : (current && current.key === l.key ? 'current' : 'todo');
            const label = state === 'done' ? 'Đã xong' : state === 'current' ? 'Đang học' : (rec ? `${rec.best}%` : 'Chưa học');
            const py = details[l.key] && details[l.key].py;
            return (
              <li class={'cur-lesson-row is-' + state}>
                <button
                  type="button"
                  class="cur-lesson-btn"
                  aria-current={state === 'current' ? 'step' : undefined}
                  onClick={() => openLesson(l.key)}
                >
                  <span class="cur-lesson-badge" aria-hidden="true">{state === 'done' ? <CheckIcon size={14} /> : l.n}</span>
                  <span class="cur-lesson-text">
                    <span class="cur-lesson-zh" lang="zh-CN">{l.zh}</span>
                    <span class="cur-lesson-sub">
                      {py && <span class="cur-lesson-py">{py}</span>}
                      {py && l.vi && <span class="cur-lesson-dot" aria-hidden="true">·</span>}
                      {l.vi && <span class="cur-lesson-vi">{l.vi}</span>}
                    </span>
                  </span>
                  <span class="cur-lesson-meta">{`${l.words} từ · ${l.grammar} ngữ pháp`}</span>
                  <span class={'cur-lesson-state is-' + state}>{label}</span>
                </button>
              </li>
            );
          })}
        </ol>
      </div>
    </div>
  );
}

function CurriculumSkeleton({ label }) {
  return (
    <div class="cur-wrap cur-skeleton" aria-busy="true">
      <span class="cur-sr-only" role="status">{label}</span>
      <div class="cur-skel cur-skel-title"></div>
      <div class="cur-skel cur-skel-line"></div>
      <div class="cur-skel cur-skel-levels"></div>
      <div class="cur-skel cur-skel-block"></div>
      {[0, 1, 2, 3].map(() => <div class="cur-skel cur-skel-row"></div>)}
    </div>
  );
}

function QuizView({ lesson, levelData }) {
  const quiz = ui.quiz;
  if (!quiz) {
    const rec = readStore().lessons[lesson.key];
    return (
      <div class="cur-card cur-quiz-start">
        <p class="cur-quiz-intro">{`Khoảng ${QUIZ_SIZE} câu trắc nghiệm (từ mới, nghe hiểu và ngữ pháp) của bài. Đúng từ 80% trở lên là hoàn thành bài.`}</p>
        {rec && <p class="cur-quiz-best">{`Điểm cao nhất: ${rec.best}%${rec.done ? ' · Đã hoàn thành' : ''}`}</p>}
        <button type="button" class="ds-btn ds-btn--primary" onClick={() => setUi({ quiz: buildQuiz(lesson, levelData) })}>Bắt đầu luyện tập</button>
      </div>
    );
  }
  const total = quiz.questions.length;
  if (quiz.finished) {
    const passed = quiz.score / total >= PASS_RATIO;
    return (
      <div class="cur-card cur-quiz-result">
        <div class="cur-quiz-score">{`${quiz.score} / ${total}`}</div>
        <p class={'cur-feedback ' + (passed ? 'is-correct' : 'is-wrong')}>{passed ? 'Hoàn thành bài! Bạn có thể sang bài tiếp theo.' : 'Chưa đạt 80%. Xem lại từ vựng và ngữ pháp rồi thử lại nhé.'}</p>
        <div class="cur-actions">
          <button type="button" class="ds-btn ds-btn--secondary" onClick={() => setUi({ quiz: buildQuiz(lesson, levelData) })}>Làm lại</button>
          {passed && <NextLessonButton lesson={lesson} levelData={levelData} />}
        </div>
      </div>
    );
  }
  const q = quiz.questions[quiz.index];
  const answered = quiz.picked !== null;
  const correct = answered && quiz.picked === q.answer;
  const choose = (opt) => {
    if (answered) return;
    setUi({ quiz: { ...quiz, picked: opt, score: quiz.score + (opt === q.answer ? 1 : 0) } });
  };
  const next = () => {
    if (quiz.index + 1 >= total) {
      recordQuizResult(lesson.key, quiz.score, total);
      setUi({ quiz: { ...quiz, finished: true } });
    } else {
      setUi({ quiz: { ...quiz, index: quiz.index + 1, picked: null } });
    }
  };
  return (
    <div class="cur-card cur-quiz">
      <div class="cur-progress"><div class="cur-progress-fill" style={`width:${Math.round((quiz.index / total) * 100)}%`}></div></div>
      <div class="cur-quiz-kind">{`Câu ${quiz.index + 1} / ${total} · ${q.kind}`}</div>
      {q.audioText && (
        <div class="cur-quiz-audio-wrap">
          <button
            type="button"
            class="cur-quiz-audio"
            onClick={(e) => speak(q.audioText, e)}
            aria-label="Nghe câu hỏi"
          >
            <AudioIcon size={20} />
            <span>Nghe và chọn đáp án đúng</span>
          </button>
        </div>
      )}
      {q.prompt && (
        <div class={'cur-quiz-prompt' + (q.promptIsZh ? ' is-zh' : '')} lang={q.promptIsZh ? 'zh-CN' : 'vi'}>{q.prompt}</div>
      )}
      {q.sub && <div class="cur-quiz-sub">{q.sub}</div>}
      <div class={'cur-quiz-options' + (q.optionsZh ? ' is-zh' : '')}>
        {q.options.map((opt) => {
          let cls = 'cur-quiz-option';
          if (answered && opt === q.answer) cls += ' is-correct';
          else if (answered && opt === quiz.picked) cls += ' is-wrong';
          return <button type="button" class={cls} disabled={answered} lang={q.optionsZh ? 'zh-CN' : 'vi'} onClick={() => choose(opt)}>{opt}</button>;
        })}
      </div>
      {answered && (
        <div class={'cur-feedback ' + (correct ? 'is-correct' : 'is-wrong')}><strong>{correct ? 'Đúng. ' : 'Chưa đúng. '}</strong>{q.explain}</div>
      )}
      {answered && (
        <div class="cur-actions cur-actions-end"><button type="button" class="ds-btn ds-btn--primary" onClick={next}>{quiz.index + 1 >= total ? 'Xem kết quả' : 'Câu tiếp theo'}</button></div>
      )}
    </div>
  );
}

function NextLessonButton({ lesson, levelData }) {
  const next = levelData.lessons.find((l) => l.n === lesson.n + 1);
  if (!next) return null;
  return <button type="button" class="ds-btn ds-btn--primary" onClick={() => openLesson(next.key)}>{`Bài ${next.n}: ${next.zh}`}</button>;
}

function LessonView({ lesson, levelData }) {
  const words = lesson.words || [];
  const shownWords = ui.showAllWords ? words : words.slice(0, 12);
  const speakers = [];
  lesson.dialogue.forEach((line) => { if (speakers.indexOf(line.who) < 0) speakers.push(line.who); });
  const known = knownCount(lesson.key);
  return (
    <div class={'cur-wrap cur-lesson' + (ui.hidePinyin ? ' cur-hide-pinyin' : '')}>
      <div class="cur-crumbs">
        <button
          type="button"
          class="cur-back"
          onClick={backToLessons}
        >
          <ChevronLeftIcon size={16} />
          {`Giáo trình ${levelData.name}`}
        </button>
        <span class="cur-crumb-count">{`Bài ${lesson.n} / ${levelData.lessons.length}`}</span>
      </div>

      <header class="cur-card cur-lesson-head">
        <div class="cur-eyebrow is-accent">{`第${lessonNumeral(lesson.n)}课 · ${levelData.name}`}</div>
        <h2 class="cur-lesson-title" lang="zh-CN" tabindex="-1">{lesson.zh}</h2>
        <div class="cur-lesson-sub"><span class="cur-py">{lesson.py}</span>{` · ${lesson.vi}`}</div>
        <div class="cur-tags">
          {lesson.topic && <span class="cur-tag">{lesson.topic}</span>}
          {lesson.grammar.map((g) => <span class="cur-tag">{g.title}</span>)}
        </div>
        <nav class="cur-sections" aria-label="Các phần của bài">
          {SECTIONS.map(([id, label], i) => (
            <button type="button" class={'cur-section-link' + (i === 0 ? ' is-first' : '')} onClick={() => scrollToSection(id)}>{`${i + 1} · ${label}`}</button>
          ))}
        </nav>
      </header>

      <section class="cur-section" id="curSection-vocab" aria-labelledby="curHeadVocab">
        <div class="cur-section-head">
          <h3 class="cur-h2" id="curHeadVocab">生词 · Từ mới <span class="cur-count">{`${words.length} từ${known ? ` · đã nhớ ${known}` : ''}`}</span></h3>
          <div class="cur-actions">
            <button type="button" class="ds-btn ds-btn--secondary" onClick={() => window.openWritingPractice && window.openWritingPractice(lesson.key)}>Tập viết bài này</button>
            <button type="button" class="ds-btn ds-btn--secondary cur-btn-accent" onClick={() => startLessonFlashcards(lesson.key)}>Học flashcard bài này</button>
          </div>
        </div>
        <div class="cur-word-grid">
          {shownWords.map((w) => (
            <button
              type="button"
              class="cur-word"
              onClick={(e) => speak(w.hanzi, e)}
              aria-label={`Nghe ${w.hanzi}`}
            >
              <span class="cur-word-hanzi" lang="zh-CN">{w.hanzi}</span>
              <span class="cur-word-info">
                <span class="cur-word-py">{w.pinyin}</span>
                <span class="cur-word-meaning">{w.meaning}</span>
                {w.hanviet && <span class="cur-word-hv">{w.hanviet}</span>}
              </span>
              <AudioIcon
                size={14}
                class="cur-word-audio"
              />
            </button>
          ))}
        </div>
        {words.length > 12 && (
          <button type="button" class="cur-link-btn" onClick={() => setUi({ showAllWords: !ui.showAllWords })}>
            {ui.showAllWords ? 'Thu gọn' : `Xem tất cả ${words.length} từ`}
          </button>
        )}
      </section>

      <section class="cur-section" id="curSection-dialogue" aria-labelledby="curHeadDialogue">
        <div class="cur-section-head">
          <h3 class="cur-h2" id="curHeadDialogue">课文 · Bài đọc{lesson.dialogueTitle ? <span class="cur-count">{lesson.dialogueTitle}</span> : null}</h3>
          <div class="cur-actions">
            <button
              type="button"
              class="ds-btn ds-btn--secondary"
              onClick={(e) => speakAll(lesson.dialogue.map((l) => l.zh), e)}
            >
              Nghe cả bài
            </button>
            <button type="button" class="ds-btn ds-btn--secondary" aria-pressed={String(ui.hidePinyin)} onClick={() => setUi({ hidePinyin: !ui.hidePinyin })}>{ui.hidePinyin ? 'Hiện pinyin' : 'Ẩn pinyin'}</button>
          </div>
        </div>
        <div class="cur-card cur-dialogue">
          {lesson.dialogue.map((line) => {
            const side = speakers.indexOf(line.who) % 2 === 0 ? 'a' : 'b';
            const glyph = line.who.length > 2 ? line.who.slice(0, 1) : line.who.slice(-1);
            return (
              <div class={'cur-line is-' + side}>
                <span class="cur-avatar" title={line.who} aria-hidden="true" lang="zh-CN">{glyph}</span>
                <div class="cur-line-body">
                  <div class="cur-line-who" lang="zh-CN">{line.who}</div>
                  <button type="button" class="cur-line-zh" lang="zh-CN" onClick={(e) => speak(line.zh, e)}>{line.zh}</button>
                  <div class="cur-py">{line.py}</div>
                  <div class="cur-line-vi">{line.vi}</div>
                </div>
              </div>
            );
          })}
        </div>
      </section>

      <section class="cur-section" id="curSection-grammar" aria-labelledby="curHeadGrammar">
        <h3 class="cur-h2" id="curHeadGrammar">语法 · Ngữ pháp</h3>
        {lesson.grammar.map((g) => (
          <article class="cur-card cur-grammar">
            <div class="cur-grammar-head">
              <h4 class="cur-grammar-title">{g.title}</h4>
              {g.tag && <span class="cur-grammar-tag" lang="zh-CN">{`HSK 3.0 · ${g.tag}`}</span>}
            </div>
            <div class="cur-formula" lang="zh-CN">{g.formula}</div>
            {g.note && <p class="cur-note">{g.note}</p>}
            <ul class="cur-examples">
              {g.examples.map((ex) => (
                <li class="cur-example">
                  <button
                    type="button"
                    class="cur-speak"
                    onClick={(e) => speak(ex.zh, e)}
                    aria-label="Nghe câu mẫu"
                  >
                    <AudioIcon size={16} />
                  </button>
                  <span class="cur-example-text">
                    <span class="cur-example-zh" lang="zh-CN">{ex.zh}</span>
                    <span class="cur-py">{ex.py}</span>
                    <span class="cur-example-vi">{ex.vi}</span>
                  </span>
                </li>
              ))}
            </ul>
          </article>
        ))}
      </section>

      <section class="cur-section" id="curSection-practice" aria-labelledby="curHeadPractice">
        <h3 class="cur-h2" id="curHeadPractice">练习 · Luyện tập</h3>
        <QuizView lesson={lesson} levelData={levelData} />
      </section>
    </div>
  );
}

function CurriculumScreen() {
  if (ui.error) {
    return (
      <div class="cur-wrap"><div class="cur-empty" role="alert">
        <span class="cur-empty-icon" aria-hidden="true">
          <RotateIcon size={22} />
        </span>
        <h2 class="cur-empty-title">Chưa tải được giáo trình</h2>
        <p class="cur-empty-text">{`${ui.error} Kiểm tra kết nối mạng rồi thử lại.`}</p>
        <button type="button" class="ds-btn ds-btn--primary" onClick={() => { ui.error = null; initCurriculum(); }}>Thử lại</button>
      </div></div>
    );
  }
  if (!indexData) return <CurriculumSkeleton label="Đang tải giáo trình…" />;
  const levelId = ui.level || indexData.levels[0].level;
  const levelData = levelCache[levelId];
  if (ui.lessonKey) {
    const lesson = levelData && levelData.lessons.find((l) => l.key === ui.lessonKey);
    if (!lesson) return <CurriculumSkeleton label="Đang tải bài học…" />;
    return <LessonView lesson={lesson} levelData={levelData} />;
  }
  return <OverviewView index={indexData} levelId={levelId} />;
}

export function initCurriculum() {
  screenEl = document.getElementById('screenCurriculum');
  if (!screenEl) return;
  const store = readStore();
  ui = { ...ui, lessonKey: null, quiz: null, level: ui.level || store.level || '1' };
  rerender();
  Promise.all([loadIndex(), loadLevel(ui.level)])
    .then(rerender)
    .catch(() => setUi({ error: 'Không tải được dữ liệu giáo trình.' }));
}

// Register one flashcard deck per lesson (hidden from the level grids) so
// selectLevel()/SpaRouter can open lesson decks, including after a reload.
export function registerCurriculumDecks() {
  if (typeof LEVELS === 'undefined') return;
  CURRICULUM_LESSONS.forEach(([key, , levelName, n, titleZh, total, parentDeck]) => {
    const parent = LEVELS[parentDeck] || {};
    LEVELS[key] = {
      label: `${levelName} · Bài ${n}: ${titleZh}`,
      band: 'Giáo trình',
      dataUrl: `${DATA_ROOT}decks/${key}.json`,
      audioManifestUrl: parent.audioManifestUrl,
      available: false,
      isLesson: true,
      total,
      version: '3.0',
    };
  });
}

export function mountCurriculum() {
  registerCurriculumDecks();
  window.Curriculum = { init: initCurriculum, openLesson, buildQuiz };
}
